import csv
import io
import re
import collections


_EXPECTED_WIDTH = 9


def _read_rows(raw_csv):
    text = raw_csv.lstrip("\ufeff")
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, AttributeError):
        pass

    try:
        return list(csv.reader(
            io.StringIO(text, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False
        ))
    except csv.Error:
        return _lenient_read(text)


def _lenient_read(text):
    rows = []
    row = []
    field = []
    quoted = False
    after_quote = False
    i = 0

    while i < len(text):
        ch = text[i]

        if quoted:
            if ch == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                quoted = False
                after_quote = True
            else:
                field.append(ch)
            i += 1
            continue

        if after_quote:
            if ch == ",":
                row.append("".join(field))
                field = []
                after_quote = False
            elif ch == "\r" or ch == "\n":
                row.append("".join(field))
                field = []
                rows.append(row)
                row = []
                after_quote = False
                if ch == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                    i += 1
            elif ch in " \t":
                pass
            else:
                field.append(ch)
                after_quote = False
            i += 1
            continue

        if ch == '"' and not field:
            quoted = True
        elif ch == ",":
            row.append("".join(field))
            field = []
        elif ch == "\r" or ch == "\n":
            row.append("".join(field))
            field = []
            rows.append(row)
            row = []
            if ch == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                i += 1
        else:
            field.append(ch)
        i += 1

    if field or row or after_quote or quoted:
        row.append("".join(field))
        rows.append(row)

    return rows


def _value_kind(value):
    s = value.strip()
    if not s:
        return "empty"
    if re.fullmatch(r"[+-]?\d+", s):
        return "integer"
    if re.fullmatch(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)", s):
        return "number"
    if re.fullmatch(r"[$€£¥]\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)", s):
        return "currency"
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[AaPp][Mm])?", s):
        return "time"
    if re.fullmatch(
        r"(?:\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4})(?:\s+.*)?",
        s
    ):
        return "date"
    if re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", s):
        return "url"
    if re.fullmatch(r"(?i:true|false|yes|no|null|none|n/a|na)", s):
        return "token"
    return "text"


def _header_score(row, index, rows):
    if len(row) != _EXPECTED_WIDTH:
        return float("-inf")

    score = 0.0
    nonempty = 0
    normalized = []

    for value in row:
        s = value.strip()
        normalized.append(s.casefold())
        if not s:
            score -= 1.5
            continue
        nonempty += 1
        kind = _value_kind(s)
        if kind == "text":
            score += 2.5
        elif kind == "token":
            score += 0.5
        else:
            score -= 3.0

        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ .()/+-]*", s):
            score += 1.0
        if len(s) > 80:
            score -= 1.0

    score += len(set(normalized)) * 0.15
    score += nonempty * 0.15

    following = rows[index + 1:index + 9]
    if following:
        exact = sum(len(r) == _EXPECTED_WIDTH for r in following)
        score += 5.0 * exact / len(following)

        structured = 0
        examined = 0
        for candidate in following:
            if len(candidate) != _EXPECTED_WIDTH:
                continue
            examined += 1
            kinds = [_value_kind(v) for v in candidate]
            if any(k in ("integer", "number", "currency", "date", "time", "url")
                   for k in kinds):
                structured += 1
        if examined:
            score += 3.0 * structured / examined

    score -= index * 0.01
    return score


def _find_header(rows):
    candidates = []
    limit = min(len(rows), 200)

    for i in range(limit):
        if len(rows[i]) == _EXPECTED_WIDTH:
            candidates.append((_header_score(rows[i], i, rows), i))

    if candidates:
        candidates.sort(key=lambda item: (-item[0], item[1]))
        return candidates[0][1]

    for i, row in enumerate(rows):
        if len(row) > 1:
            return i
    return 0


def _make_profiles(rows, width):
    counts = [collections.Counter() for _ in range(width)]
    lengths = [[] for _ in range(width)]
    comma_counts = [0] * width
    totals = [0] * width

    conforming = [r for r in rows if len(r) == width]
    source = conforming if conforming else rows

    for row in source:
        if len(row) != width:
            continue
        for i, value in enumerate(row):
            counts[i][_value_kind(value)] += 1
            lengths[i].append(len(value))
            comma_counts[i] += value.count(",")
            totals[i] += 1

    profiles = []
    for i in range(width):
        total = sum(counts[i].values())
        average_length = (
            sum(lengths[i]) / len(lengths[i]) if lengths[i] else 0.0
        )
        comma_rate = comma_counts[i] / totals[i] if totals[i] else 0.0
        profiles.append((counts[i], total, average_length, comma_rate))

    return profiles


def _compatibility(value, profile):
    counts, total, average_length, comma_rate = profile
    kind = _value_kind(value)

    if total:
        frequency = counts[kind] / total
        score = frequency * 9.0
        dominant = counts.most_common(1)[0][0]
        if kind == dominant:
            score += 2.5
        elif kind == "text" and dominant == "text":
            score += 1.0
        elif kind != "empty" and dominant == "empty":
            score -= 5.0
        elif kind == "empty" and dominant != "empty":
            score -= 3.5
        elif kind != dominant:
            score -= 2.5
    else:
        score = 0.0

    if average_length > 0 and value:
        difference = abs(len(value) - average_length)
        score -= min(3.0, difference / max(8.0, average_length))

    if "," in value:
        score += min(3.0, comma_rate * 4.0)

    return score


def _repair_long_row(row, width, profiles):
    count = len(row)
    negative = float("-inf")
    dp = [[negative] * (count + 1) for _ in range(width + 1)]
    previous = [[None] * (count + 1) for _ in range(width + 1)]
    dp[0][0] = 0.0

    for column in range(width):
        remaining_columns = width - column - 1
        for consumed in range(count + 1):
            base = dp[column][consumed]
            if base == negative:
                continue

            maximum_take = count - consumed - remaining_columns
            for take in range(1, maximum_take + 1):
                value = ",".join(row[consumed:consumed + take])
                score = base + _compatibility(value, profiles[column])
                if take > 1:
                    score -= 1.25 * (take - 1)
                    score += min(
                        4.0,
                        profiles[column][3] * 3.0 * (take - 1)
                    )
                target = consumed + take
                if score > dp[column + 1][target]:
                    dp[column + 1][target] = score
                    previous[column + 1][target] = (consumed, value)

    if previous[width][count] is None:
        return row[:width - 1] + [",".join(row[width - 1:])]

    result = [""] * width
    position = count
    for column in range(width, 0, -1):
        prior, value = previous[column][position]
        result[column - 1] = value
        position = prior
    return result


def _repair_short_row(row, width, profiles):
    count = len(row)
    negative = float("-inf")
    dp = [[negative] * (count + 1) for _ in range(width + 1)]
    previous = [[None] * (count + 1) for _ in range(width + 1)]
    dp[0][0] = 0.0

    for column in range(width):
        for consumed in range(count + 1):
            base = dp[column][consumed]
            if base == negative:
                continue

            empty_score = base + _compatibility("", profiles[column]) - 1.5
            if empty_score > dp[column + 1][consumed]:
                dp[column + 1][consumed] = empty_score
                previous[column + 1][consumed] = (consumed, "")

            if consumed < count:
                value = row[consumed]
                value_score = base + _compatibility(value, profiles[column])
                if value_score > dp[column + 1][consumed + 1]:
                    dp[column + 1][consumed + 1] = value_score
                    previous[column + 1][consumed + 1] = (
                        consumed,
                        value
                    )

    if previous[width][count] is None:
        return row + [""] * (width - count)

    result = [""] * width
    position = count
    for column in range(width, 0, -1):
        prior, value = previous[column][position]
        result[column - 1] = value
        position = prior
    return result


def parse_csv(raw_csv: str):
    rows = _read_rows(raw_csv)
    if not rows:
        return {"columns": [], "rows": []}

    header_index = _find_header(rows)
    header = list(rows[header_index])

    if len(header) < _EXPECTED_WIDTH:
        header.extend([""] * (_EXPECTED_WIDTH - len(header)))
    elif len(header) > _EXPECTED_WIDTH:
        header = header[:_EXPECTED_WIDTH - 1] + [
            ",".join(header[_EXPECTED_WIDTH - 1:])
        ]

    data_rows = rows[header_index + 1:]
    profiles = _make_profiles(data_rows, _EXPECTED_WIDTH)
    normalized = []

    for row in data_rows:
        row = list(row)
        if len(row) == _EXPECTED_WIDTH:
            normalized.append(row)
        elif len(row) > _EXPECTED_WIDTH:
            normalized.append(
                _repair_long_row(row, _EXPECTED_WIDTH, profiles)
            )
        else:
            normalized.append(
                _repair_short_row(row, _EXPECTED_WIDTH, profiles)
            )

    return {"columns": header, "rows": normalized}
